def invoke_function(func, ...args):
    return func(*args)

print(invoke_function(None, 10, 20))  # None, 10, 20
print(invoke_function(None, 10, 20, 'hello'))  # None, 10, 20, 'hello'
print(invoke_function(None, 10, 20, True))  # None, 10, 20, True
